def cells_to_both_oceans(heights):
    if not heights or not heights[0]:
        return []
    m, n = len(heights), len(heights[0])

    def reach(starts):
        seen = [[False] * n for _ in range(m)]
        stack = list(starts)
        for r, c in starts:
            seen[r][c] = True
        while stack:
            r, c = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and not seen[nr][nc] and heights[nr][nc] >= heights[r][c]:
                    seen[nr][nc] = True
                    stack.append((nr, nc))
        return seen

    a_starts = [(0, c) for c in range(n)] + [(r, 0) for r in range(m)]
    b_starts = [(m - 1, c) for c in range(n)] + [(r, n - 1) for r in range(m)]
    a = reach(a_starts)
    b = reach(b_starts)
    return [[r, c] for r in range(m) for c in range(n) if a[r][c] and b[r][c]]
